/** Release gate: every track that is not production-approved. Must be empty before public beta. */
export function unapprovedTracks(catalogue: readonly ReflectionTrack[]): ReflectionTrack[] {
  return catalogue.filter((t) => t.approval !== 'production_approved');
}
